{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is unreported; missing information does not establish that it occurred or did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish stability across runs."
        }
      ],
      "instrument_review": "MESA 14: Not sure, because repeated testing is unreported. MESA 16: variation across runs is not established."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run provides no evidence of stability across runs; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA 14: No, because the developers explicitly did not repeat testing. Stability remains unknown."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The two-percentage-point range meets the report's stated stability criterion."
        }
      ],
      "instrument_review": "MESA 14: Yes, repeated testing occurred. The observed range supports stability under the supplied definition for this comparison."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same conditions occurred regardless of its unfavourable results."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes, repeated testing occurred. Its findings contradict stability under the report's definition; testing and favourable results are separate issues."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish that repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "No additional findings establish variation or stability across runs."
        }
      ],
      "instrument_review": "MESA 14: Not sure. Installation documentation is relevant to MESA 22 on reproducibility, but does not supply evidence of repeated testing or stability."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A performed better on the evaluated puzzles under the reported scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish relative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 20: broader performance is not established. Under MESA 25, the stated intended use stays within the evaluated grid-puzzle comparison."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported results support A's better performance on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not provide evidence of greater general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 9 and 20: grid-only evidence does not establish coverage or performance across domains. MESA 25: using these findings to select for general intelligence would exceed their demonstrated scope."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an improvement in the unmeasured safety outcome."
        }
      ],
      "instrument_review": "MESA 20: the later trial supplies evidence for decision correctness beyond the initial test, limited to the studied workshop and conditions. MESA 16: an uncertainty interval supports that comparison. MESA 25: safety claims would exceed the measured outcomes."
    }
  ],
  "closing_note": "No instructions required clarification. Statement labels are distinct from MESA ratings; missing evidence was not treated as contradiction."
}
